  window.STUDY_DATA.questions.push({"id":"mock-cjing-001","module":"major","subject":"C语言程序设计","chapter":"ch-c-1","knowledgePoint":"位运算与表达式","type":"single","typeLabel":"单选","stem":"char a = 6, b; b = a << 2; 则 b 的值是（ ）","options":["12","24","48","6"],"answer":"24","pitfalls":["把 << 2 当成乘 2：左移 n 位是乘 2ⁿ，移 2 位是乘 4","选 12：那是乘 2，只移了 1 位","选 48：那是乘 8，移了 3 位","忽略 char 的 8 位上限：本题安全，但换个大数就要考虑溢出"],"difficulty":1,"difficultyLabel":"基础","source":"mock-migrated","tags":["C语言精编","迁入"],"hint":"a=6 的二进制是 00000110，左移 2 位得 00011000 = 24，选 B。","analysis":"【审题】char a=6，b=a<<2，求 b。考左移运算符与二进制换算。【定律/公式】a<<n 等于 a②ⁿ（未溢出时）；6 的二进制 0000 0110 左移 2 位为 0001 1000。【分步推导】① 6 = 110(2)。② 左移两位补零得 11000(2)=24。③ 用 6④ 核对。④ char 范围 −128~127，24 不溢出。【答案】24（选项 B）。【易错】把位移当乘法倍数错；移 1 位与 2 位混；误算乘 8；忽略类型范围。","steps":["【秒懂考点】b = a << 2 表示把 6 的二进制左移 2 位，得 24，等于 6 × 4","【第一步：写出 6 的二进制】6 = 0000 0110（按 8 位看）","【第二步：左移 2 位】0000 0110 左移两位，低两位补 0：0001 1000，即十进制 24","【第三步：用乘法快速核对】左移 1 位等于乘 2，左移 2 位等于乘 4，故 6 × 4 = 24。这是位运算最快的验算方式","【第四步：注意数据类型边界】char 通常占 8 位，取值 −128~127，24 完全在范围内，不会溢出。若左移后超过范围（如 100 << 3），结果会被截断或按有符号解释变负，这类题必须验算范围","【答案】24（B）"]});
  window.STUDY_DATA.questions.push({"id":"mock-cjing-002","module":"major","subject":"C语言程序设计","chapter":"ch-c-1","knowledgePoint":"位运算与表达式","type":"single","typeLabel":"单选","stem":"表达式 0 ^ 1 的运算结果是（ ）","options":["0","1","2","-1"],"answer":"1","pitfalls":["把 ^ 当成数学上的乘方：C 语言里 ^ 是异或，不是幂运算","与 & 混淆：0 & 1 结果为 0","与 | 混淆：虽然本题结果都是 1，但规则不同，换个输入就会出错","以为异或结果是布尔值：按位运算得到的是整数"],"difficulty":1,"difficultyLabel":"基础","source":"mock-migrated","tags":["C语言精编","迁入"],"hint":"异或 ^ 规则：相同为 0，不同为 1；0 和 1 不同，结果为 1，选 B。","analysis":"【审题】求 0 ^ 1。考按位异或的规则，并与按位与、按位或区分。【定律/公式】^：同为 0、异为 1；&：全 1 才 1；|：有 1 则 1。性质 a^a=0、a^0=a。【分步推导】① 0 与 1 不同。② 该位得 1。③ 对照 & 与 | 的同输入结果。④ 记两条性质。【答案】1（选项 B）。【易错】当成乘方；与 & 混；与 | 混；以为返回布尔值。","steps":["【秒懂考点】^ 是异或运算符，规则为\"相同得 0，不同得 1\"，0 与 1 不同，故结果为 1","【第一步：分清三种逻辑运算】& 按位与（都 1 才 1）、| 按位或（有 1 就 1）、^ 按位异或（不同才 1）","【第二步：按位计算 0 ^ 1】0 与 1 不同，该位结果为 1","【第三步：易混情形对照】0 & 1 = 0；0 | 1 = 1；0 ^ 1 = 1。本题与\"或\"结果相同，但运算规则完全不同","【第四步：异或的两个常用性质】a ^ a = 0；a ^ 0 = a。利用这两条可以做交换与去重，也是考试常考的点","【答案】1（B）"]});
  window.STUDY_DATA.questions.push({"id":"mock-cjing-003","module":"major","subject":"C语言程序设计","chapter":"ch-c-1","knowledgePoint":"位运算与表达式","type":"single","typeLabel":"单选","stem":"表达式 (5 >= 5) && (7 > 5) 的值是（ ）","options":["0","1","true（但无法用整数表示）","编译错误"],"answer":"1","pitfalls":["选 true：C 的关系运算返回 int 1，不是布尔字面量（除非引入 stdbool.h）","选编译错误：这种表达式完全合法","把 >= 当成 >：5>=5 成立，若按 > 判则为假","忽略短路：以为右侧出错也会影响结果，本题右侧正常所以不影响"],"difficulty":1,"difficultyLabel":"基础","source":"mock-migrated","tags":["C语言精编","迁入"],"hint":"5>=5 为真、7>5 为真；与运算 && 两边都为真结果为真，C 中真用整数 1 表示，选 B。","analysis":"【审题】求 (5>=5)&&(7>5) 的值。考关系运算与逻辑与。【定律/公式】关系运算结果为 int：真 1、假 0；A&&B 两者皆真才为 1；&& 有短路特性。【分步推导】① 5>=5 → 1。② 7>5 → 1。③ 1&&1 → 1。【答案】1（选项 B）。【易错】写 true；误判编译错误；>= 与 > 混；忽视短路。","steps":["【秒懂考点】(5>=5) 为真、(7>5) 为真，真 && 真 得 1；C 语言用整数 1 表示真","【第一步：逐个求子表达式】5>=5 成立，值为 1；7>5 成立，值为 1","【第二步：套 && 规则】逻辑与：两个都为真才为真。1 && 1 = 1","【第三步：为什么答案不是 true】C 语言没有布尔类型（C99 前），关系与逻辑运算的结果是 int，真为 1、假为 0。写成 true 的选项不符合 C 的取值规则","【第四步：短路特性补充】&& 从左往右算，左边为假时右边不再计算。本题左边为真，右边也计算了，但结果仍由两者共同决定","【答案】1（B）"]});
  window.STUDY_DATA.questions.push({"id":"mock-cjing-004","module":"major","subject":"C语言程序设计","chapter":"ch-c-1","knowledgePoint":"位运算与表达式","type":"single","typeLabel":"单选","stem":"表达式 (5 >= 5) || (5 > 8) 的值是（ ）","options":["0","1","2","编译错误"],"answer":"1","pitfalls":["选 0：把 || 当成了\"两者都要真\"","选 2：以为逻辑或会把真值相加","忽略短路：本题结果正确，但若追问\"5>8 是否被计算\"就答错","把 || 与按位或 | 混：1|0=1 结果相同，但运算层次不同"],"difficulty":1,"difficultyLabel":"基础","source":"mock-migrated","tags":["C语言精编","迁入"],"hint":"5>=5 为真；或运算 || 只要有一个为真结果就为真，选 1，即 B。","analysis":"【审题】求 (5>=5)||(5>8)。考逻辑或与短路求值。【定律/公式】A||B：有一个真即为 1；|| 左侧为真则右侧不求值。与 && 对照：&& 需两者都真。【分步推导】① 左侧 1。② 右侧 0。③ 1||0→1。④ 说明短路使右侧未被求值。【答案】1（选项 B）。【易错】当成都要真；真值相加；忽视短路；与按位或混。","steps":["【秒懂考点】(5>=5) 为真，(5>8) 为假，真 || 假 得 1","【第一步：求子表达式】5>=5 → 1；5>8 → 0","【第二步：套 || 规则】逻辑或：只要有一个为真就为真。1 || 0 = 1","【第三步：短路在这里体现】|| 从左往右算，左边已经是 1，右边 5>8 根本不会被求值。这也是常考细节：若右边含副作用（如 i++），它不会执行","【第四步：与 && 对照】同样的两个子表达式用 && 则为 0（因为有一个为假），这是逻辑与、逻辑或的核心差别","【答案】1（B）"]});
  window.STUDY_DATA.questions.push({"id":"mock-cjing-005","module":"major","subject":"C语言程序设计","chapter":"ch-c-1","knowledgePoint":"位运算与表达式","type":"single","typeLabel":"单选","stem":"表达式 !(5 > 8) 的值是（ ）","options":["0","1","5","8"],"answer":"1","pitfalls":["选 0：把 5>8 的结果与取反后的结果搞混","选 5 或 8：以为 ! 会把操作数本身取反成别的数","忽略优先级：忘加括号时 !5>8 的含义完全不同","以为结果是布尔类型：仍是 int 1"],"difficulty":1,"difficultyLabel":"基础","source":"mock-migrated","tags":["C语言精编","迁入"],"hint":"5>8 为假；非运算 ! 把假变真，结果为 1，选 B。","analysis":"【审题】求 !(5>8)。考逻辑非与运算符优先级。【定律/公式】关系式为假得 0；!0=1；! 的优先级高于 && 与 ||，但比较运算先于逻辑运算结合，括号可强制顺序。【分步推导】① 5>8→0。② !0→1。③ 对比 !5>8 的解析为 (!5)>8→0。④ 记优先级。【答案】1（选项 B）。【易错】结果混淆；把操作数当结果；忽略优先级；误判类型。","steps":["【秒懂考点】5>8 为假（0），!0 得 1","【第一步：先算括号里的关系式】! 的优先级低于比较运算，所以先算 5>8，结果为 0","【第二步：取反】!0 = 1。逻辑非就是把真变假、假变真，且结果仍是 int 型 1 或 0","【第三步：常见错误对照】若写成 !5>8 而不加括号，等价于 (!5)>8，即 0>8，结果为 0 — 这是优先级陷阱，本题有括号所以安全","【第四步：顺带记住优先级】! 高于算术运算以外的多数运算，但低于括号；比较运算高于逻辑与/或。不确定就加括号","【答案】1（B）"]});
  window.STUDY_DATA.questions.push({"id":"mock-cjing-006","module":"major","subject":"C语言程序设计","chapter":"ch-c-1","knowledgePoint":"位运算与表达式","type":"judge","typeLabel":"判断","stem":"在没有数据溢出丢失的情况下，将一个整数左移一位，其值相当于乘以 2。","options":["正确","错误"],"answer":"正确","pitfalls":["忽略\"无溢出\"前提就判错：有溢出时结论不成立，但题目已限定","把左移当成立方或平方：位移 n 位才是乘 2ⁿ","与右移混淆：右移对负数涉及符号位补齐，性质不同","以为左移会改变符号位：有符号数左移确实可能改变符号，这正是题目要排除的溢出情形"],"difficulty":1,"difficultyLabel":"基础","source":"mock-migrated","tags":["C语言精编","迁入"],"hint":"左移一位、低位补 0，相当于乘 2；前提是高位没有数据被移出丢失，故正确。","analysis":"【审题】判断\"无溢出时整数左移一位等于乘 2\"。考位移与乘法的等价关系及其前提。【定律/公式】a<<n = a②ⁿ（不溢出）；第 k 位权值为 2ᵏ。右移对无符号数相当于除以 2。【分步推导】① 位权翻倍解释。② 5→10、3→6 举例验证。③ 题干已排除溢出。④ 与右移性质区分。【答案】正确。【易错】忽略前提；位移倍数错；左右移混；忽视符号位。","steps":["【秒懂考点】左移 1 位在二进制上就是把每一位的权值提高一倍，等价于乘 2，故说法正确","【第一步：从位权理解】一个数的第 k 位代表 2ᵏ。左移一位后，原来第 k 位移到第 k+1 位，权值变为 2ᵏ⁺¹，正好翻倍","【第二步：举小例验证】5 = 101(2)，左移一位得 1010(2) = 10 = 5×2；3 = 11(2) 左移得 110(2) = 6 = 3×2","【第三步：注意题干的限定条件】\"没有数据溢出丢失\"是关键：若最高位被挤出去，结果就不再等于乘 2（例如 8 位有符号数 100 << 1 会越界）。题目已排除这种情况，故结论成立","【第四步：右移的差别】右移一位对无符号数是除以 2；对有符号负数，算术右移补符号位，结果与\"除以 2 取整\"不完全等价，不要与本题结论混用","【答案】正确"]});

