window.STUDY_DATA.questions.push({"id":"fp-c-01","module":"major","subject":"C语言程序设计","chapter":"ch-c-4","knowledgePoint":"数组与字符串","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"定义整型数组 int a[5]={1,2,3,4,5};，则a[2]的值为______，数组最后一个元素a[4]的值为______。","answer":"3,5","accept":["3","5"],"steps":["【秒懂考点】a[2] 是第 3 个元素，值为 3；a[4] 是最后一个元素，值为 5","【第一步：确认下标从 0 起】int a[5]={1,2,3,4,5} 的元素依次是 a[0]=1、a[1]=2、a[2]=3、a[3]=4、a[4]=5","【第二步：取 a[2]】按上面的对应关系，a[2]=3","【第三步：取 a[4]】长度 5 的最后一个下标是 4，a[4]=5","【第四步：记法】\"第 k 个元素的下标是 k−1\"，反之\"下标 i 对应第 i+1 个元素\"。本题最容易错的是把 a[2] 当成第 2 个元素答成 2 —— 差一位是数组题最高频的错误","【答案】3，5"],"analysis":"【审题】int a[5]={1,2,3,4,5}，求 a[2] 与 a[4]。考下标与序号的对应。【定律/公式】下标从 0 起；第 k 个元素下标 k−1；长度 n 的最大下标 n−1。【分步推导】① 列出对应关系。② a[2]=3。③ a[4]=5。④ 差一位的常见错误。【答案】3、5。【易错】下标当序号；末元素错位；误判越界；答案顺序反。","tags":["填空","数组"],"source":"大纲填空题","score":5,"pitfalls":["答 a[2]=2：把下标当序号，差一位","答 a[4]=4：同样差一位，且 5 个元素的最大下标才是 4","答 a[4] 越界：本题长度 5，a[4] 合法","把两个空的顺序写反：答案格式是\"3,5\""]});

window.STUDY_DATA.questions.push({"id":"fp-c-02","module":"major","subject":"C语言程序设计","chapter":"ch-c-5","knowledgePoint":"函数","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"C语言中函数定义时，若函数没有返回值，应将返回类型声明为______；函数调用时参数传递默认是______传递。","answer":"void,值","accept":["void","值"],"steps":["【秒懂考点】函数没有返回值时返回类型写 void；C 的参数传递默认是值传递","【第一步：第一空填 void】void 是空类型，表示函数不返回任何值。这类函数通常通过指针参数或全局变量把结果带出去，例如 void swap(int *a,int *b)","【第二步：第二空填\"值\"】C 语言只有值传递：调用时把实参的值复制给形参，函数内改形参不影响实参","【第三步：两个空的内在联系】正因为返回值可以没有（void），想让函数\"改外面的东西\"就只能靠指针参数 —— 这两点在实际编码里是一套配合关系","【第四步：常见错误】把返回类型写成 int 却又不 return，返回值不确定且编译器会警告；把传递方式写成\"地址传递\"或\"引用传递\"，C 里没有这两种独立机制（传地址仍是值传递，C++ 才有引用）","【答案】void，值"],"analysis":"【审题】填两空：无返回值时的返回类型、参数传递方式。考 void 与值传递。【定律/公式】void 表示无返回值；C 仅值传递；传指针可间接改实参但仍属值传递；C++ 才有引用传递。【分步推导】① void 的语义。② 值传递的语义。③ 两者与指针参数的配合。④ 常见错误与警告。【答案】void、值传递。【易错】写 int；写地址传递；写引用传递；void 里返回值。","tags":["填空","函数"],"source":"大纲填空题","score":5,"pitfalls":["第一空写 int：没有返回值就该用 void","第二空写\"地址传递\"：C 没有该机制，传地址仍是值传递","第二空写\"引用传递\"：那是 C++ 的概念","void 函数里写 return 值：语法错误"]});

window.STUDY_DATA.questions.push({"id":"fp-c-03","module":"major","subject":"C语言程序设计","chapter":"ch-c-6","knowledgePoint":"指针","type":"fill","typeLabel":"填空","difficulty":2,"difficultyLabel":"强化","stem":"若int a=10; int *p=&a;，则*p的值为______，&a的值为______（填含义）。","answer":"10,a的内存地址","accept":["10","地址"],"steps":["【秒懂考点】*p 是 p 所指变量的值，即 10；&a 是 a 在内存中的地址","【第一步：建立指向关系】int *p=&a 让 p 保存 a 的地址，所以 p 与 &a 是同一个值","【第二步：第一空求值】*p 解引用，取出该地址里存的内容，即 a 的值 10","【第三步：第二空求地址】&a 是取地址运算，得到 a 的内存地址，通常用十六进制表示，形式如 0x0061FF1C（具体值每次运行可能不同）","【第四步：三层关系一定要分清】p（存地址）、*p（存的值 10）、&p（指针自己所在的地址，与 a 的地址不同）。这三层是 C 指针题的基本功，答错多半是把它们混在一起","【答案】10，a 的内存地址"],"analysis":"【审题】int a=10；int *p=&a，求 *p 与 &a。考指针的三层关系。【定律/公式】p=&a；*p 取该地址的值；&a 为 a 的地址；&p 为指针自身地址（不同于 &a）。【分步推导】① p=a 的地址。② *p=10。③ &a=地址。④ 三层区分。【答案】10、a 的内存地址。【易错】两空颠倒；值与地址混；误认地址固定；层级搞错。","tags":["填空","指针"],"source":"大纲填空题","score":5,"pitfalls":["两个空写反：把 *p 写成地址、&a 写成 10","把 &a 写成 a：一个是值一个是地址","以为 &a 是固定的固定常量：每次运行可能变化","多套一层：&p 才是指针自身的地址"]});

